def keys_with_value(aDict, target):
    target_keys = []
    for i in aDict.keys():
        if aDict[i] == target:
            target_keys.append(i)
    target_keys.sort()
    return target_keys

def all_positive(d):
    L = []
    for k, v in d.items():
        if sum(v) > 0:
            L.append(k)
    return sorted(L)
